// e2e/checkout.spec.ts
import { test, expect } from '@playwright/test';

test('User can successfully checkout', async ({ page }) => {
  // 1. Navigate to the fully running Next.js app
  await page.goto('http://localhost:3000');

  // 2. Automate user behavior
  await page.click('text=Buy Now');
  await page.fill('input[name="email"]', 'test@example.com');
  await page.fill('input[name="creditCard"]', '4242424242424242');
  await page.click('button:has-text("Place Order")');

  // 3. Assert the entire system worked end-to-end
  await expect(page).toHaveURL('/order-success');
  await expect(page.locator('h1')).toContainText('Thank you for your purchase');
});
